/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    /* CONSIDERATIONS
    - for CCR/not CCR always look at the shipment line picked qty
    - A new supplier WH field added against SL (CB238) and they can be different, could have one with CCR/Pick director and another one without
    - CCR data
        * A Tote ID (repack case) can be split across different orders e.g. 6004293661 SO0001 and SO0003
            + Then avoid counting the same Tote Id twice for the TS
        * An item from the same SO can be split in different Tote ID e.g. SO0001 item ABS in Tote ID 6004293661 and 6004293714
        *
    */

    METTMSShipmentTable         tmsShipmentTable;
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    ttsbegin;
    // test update_recordset
    // previous PalletTotalFootprint 12.670587
    /*update_recordset tmsShipmentTable
        setting TMSSendStatus = METTMSSendStatus::ToBeSent,
                ShipmentStatus = METCashShipmentStatus::Active,
                PalletLifts = tmsShipmentOrderTable.PalletTotalFootprint
        // VNG join sum doesn't seem to work with update_recordset
    join sum(PalletTotalFootprint) from tmsShipmentOrderTable
            where tmsShipmentOrderTable.ShipmentId == tmsShipmentTable.ShipmentID
               //&& tmsShipmentOrderTable.OrderNumber == salesTable.SalesId;
               && tmsShipmentTable.ShipmentId == "025-71289183-R44-20241025";*/

    // calc sum PalletTotalFootprint for the shipment
    select sum(PalletTotalFootprint) from tmsShipmentOrderTable
            where tmsShipmentOrderTable.ShipmentId == "025-71289183-R44-20241025";

    update_recordset tmsShipmentTable
        setting TMSSendStatus = METTMSSendStatus::ToBeSent,
                ShipmentStatus = METCashShipmentStatus::Active,
                PalletLifts = tmsShipmentOrderTable.PalletTotalFootprint
        // VNG join sum doesn't seem to work with update_recordset
        where tmsShipmentTable.ShipmentID == "025-71289183-R44-20241025";
    /*join sum(PalletTotalFootprint) from tmsShipmentOrderTable
            where tmsShipmentOrderTable.ShipmentId == tmsShipmentTable.ShipmentID
               && tmsShipmentOrderTable.OrderNumber == salesTable.SalesId;
               && tmsShipmentOrderTable.ShipmentId == _tmsShipmentId;*/

    ttscommit;
}
